import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'

const root = '/home/user/deepseek-harness/.claude/worktrees/agent-a1fdba0b8838c765d'

function walk(dir) {
  const out = []
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, entry.name)
    if (entry.isDirectory()) out.push(...walk(p))
    else out.push(p)
  }
  return out
}

const targets = [
  ...walk(join(root, 'data/knowledge/code-safety')),
  join(root, '.agents/notes/implemented/process/2026-09-19-code-safety-knowledge-pack.md'),
  join(root, '.agents/notes/implemented/process/2026-09-19-code-safety-knowledge-pack.zh.md'),
  join(root, '.agents/notes/implemented/process/2026-09-19-code-safety-knowledge-pack.i18n.yaml'),
]

let allOk = true
for (const file of targets.sort()) {
  const buf = readFileSync(file)
  const text = buf.toString('utf8')
  const rel = file.slice(root.length + 1)
  const endsOneNewline = buf[buf.length - 1] === 0x0a && buf[buf.length - 2] !== 0x0a
  const words = text
    .split(/^---$/m)
    .filter((_, i, arr) => !(arr.length >= 3 && i === 1)) // drop frontmatter block if present
  const bodyForCount = rel.endsWith('SKILL.md') && text.startsWith('---\n')
    ? text.split('---\n').slice(2).join('---\n')
    : text
  const wc = bodyForCount.trim().split(/\s+/).filter(Boolean).length
  if (!endsOneNewline) allOk = false
  console.log(`${endsOneNewline ? 'OK ' : 'BAD'}  newline=${endsOneNewline}  words=${String(wc).padStart(5)}  ${rel}`)
}
console.log(allOk ? '\nAll files end with exactly one trailing newline.' : '\nSOME FILES FAIL trailing-newline check.')

