import { readFileSync } from 'node:fs'
import { parse as parseYaml } from 'yaml'

const root = '/home/user/deepseek-harness/.claude/worktrees/agent-a1fdba0b8838c765d'
const dirs = [
  'review-method', 'owasp-top-10', 'cwe-top-25', 'secrets', 'injection',
  'access', 'data', 'dependencies', 'platform', 'severity-and-evidence', 'report-template',
]
const kebab = /^[a-z0-9]+(-[a-z0-9]+)*$/

for (const dir of dirs) {
  const path = `${root}/data/knowledge/code-safety/${dir}/SKILL.md`
  const raw = readFileSync(path, 'utf8')
  const firstLineEnd = raw.indexOf('\n')
  const firstLine = raw.slice(0, firstLineEnd)
  if (firstLine !== '---') { console.log(`${dir}: FAIL no leading ---`); continue }
  const closeIdx = raw.indexOf('\n---', firstLineEnd)
  const yamlText = raw.slice(firstLineEnd + 1, closeIdx + 1)
  let data
  try {
    data = parseYaml(yamlText)
  } catch (error) {
    console.log(`${dir}: YAML PARSE ERROR: ${error.message}`)
    continue
  }
  const nameOk = data.name === dir
  const kebabOk = kebab.test(data.name)
  const descLen = typeof data.description === 'string' ? data.description.length : -1
  const keys = Object.keys(data).sort().join(',')
  console.log(`${dir}: parsed OK, name=${JSON.stringify(data.name)} nameMatchesDir=${nameOk} kebab=${kebabOk} descLen=${descLen} keys=[${keys}]`)
}

